export function interpolateArcRotateCamera(camera, scene, goal, signal, options) {
  return new Promise((resolve, reject) => {
    const factor = options?.interpolationFactor ?? 0.1;
    const goalAlpha = goal.alpha;
    const goalBeta = goal.beta;
    const goalRadius = goal.radius;
    const goalTarget = goal.target;
    let t = 0;
    const update = () => {
      if (goalAlpha !== undefined) camera.alpha += (goalAlpha - camera.alpha) * factor;
      if (goalBeta !== undefined) camera.beta += (goalBeta - camera.beta) * factor;
      if (goalRadius !== undefined) camera.radius += (goalRadius - camera.radius) * factor;
      if (goalTarget) {
        camera.target.x += (goalTarget.x - camera.target.x) * factor;
        camera.target.y += (goalTarget.y - camera.target.y) * factor;
        camera.target.z += (goalTarget.z - camera.target.z) * factor;
      }
      if (settled) { resolve(); scene.onFrame.remove(update); }
    };
    scene.onFrame.add(update);
  });
}
```
